CREATE TABLE nextcloud_capacity_scopes (scope_id TEXT PRIMARY KEY,total_bytes BIGINT NOT NULL,available_bytes BIGINT NOT NULL,measured_at_ms BIGINT NOT NULL,state TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1);
CREATE TABLE nextcloud_capacity_policies (tenant_id BIGINT NOT NULL,knowledge_base_id TEXT NOT NULL,retention_quota_bytes BIGINT NOT NULL DEFAULT 0,warning_percent INTEGER NOT NULL DEFAULT 80,pause_percent INTEGER NOT NULL DEFAULT 90,PRIMARY KEY(tenant_id,knowledge_base_id),CHECK(retention_quota_bytes>=0 AND warning_percent>0 AND warning_percent<pause_percent AND pause_percent<=100));
CREATE TABLE nextcloud_capacity_reservations (token TEXT PRIMARY KEY,scope_id TEXT NOT NULL REFERENCES nextcloud_capacity_scopes(scope_id),tenant_id BIGINT NOT NULL,knowledge_base_id TEXT NOT NULL,backend_id TEXT NOT NULL,request_key TEXT NOT NULL,bytes BIGINT NOT NULL CHECK(bytes>0),state TEXT NOT NULL,lease_until_ms BIGINT NOT NULL,created_at_ms BIGINT NOT NULL,committed_at_ms BIGINT NOT NULL DEFAULT 0,UNIQUE(tenant_id,knowledge_base_id,request_key));
CREATE INDEX nextcloud_capacity_pending ON nextcloud_capacity_reservations(scope_id,state,lease_until_ms);
